package android.content; public class Intent { private final java.util.Map<String,Object> values=new java.util.HashMap<>(); public Intent putExtra(String k,boolean v){values.put(k,v);return this;} public Intent putExtra(String k,String[] v){values.put(k,v);return this;} public boolean getBooleanExtra(String k,boolean d){return values.containsKey(k)?(Boolean)values.get(k):d;} public String[] getStringArrayExtra(String k){return (String[])values.get(k);} }